import {setupWetLab} from './wetlab-ui.js';
import {setupModels} from './model-setup.js';
import {createReefMap} from './reef-map.js';
import {setupCompoundUI} from './compound-ui.js';
import {chemicalModels,accessLabels,worldLabels} from './research.js';
import {SITES} from './data.js';
import {comparisonVisuals,budgetVisual} from './visuals.js';
import {scenarioRisk,rng,VERSION} from './engine.js';
let geo={type:'FeatureCollection',features:[]};
try{const r=await fetch('land.geojson');if(r.ok)geo=await r.json();}catch(error){console.error(error);}
const $=id=>document.getElementById(id), state={horizon:14,basin:'all',site:SITES[0],layer:'risk',delta:{heat:0,light:0,mixing:0},run:null};
const color=r=>r>=70?'#ec9178':r>=40?'#e5c27d':'#72b9a5';
const fmt=(v,d=3)=>v==null?'—':Number(v).toFixed(d);
const route={local:'局地',neighbor:'邻域',directional:'方向性'},model={additive:'加性',interaction:'交互项',...Object.fromEntries(chemicalModels.map(m=>[m.id,m.short]))};
const visible=()=>SITES.filter(s=>state.basin==='all'||s.basin===state.basin);
const risk=s=>scenarioRisk(s,state.horizon);
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800);}
function download(name,text,type='application/json;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function evidence(s){return s.evidence==='A'?`A · 模拟调查 ${s.bleaching}%`:s.evidence==='B'?'B · 模拟事件报告':'U · 未调查 / 未知';}
function outcome(s){return s.outcome?`${s.outcome}示例`:'未评估';}
function next(s){return s.evidence==='U'?'补充白化调查，记录类群、深度及样本量':s.evidence==='B'?'核对报告来源，并用标准化样带复核':'安排重复调查，分别记录白化、恢复与死亡';}
function metric(label,number,unit,note){return `<div class="stat"><div class="label">${label}</div><div class="number">${number}<small>${unit}</small></div><div class="note">${note}</div></div>`;}
function drawSummary(){const sites=visible();$('summary').innerHTML=metric('演示礁区',String(sites.length).padStart(2,'0'),'个','地名为展示锚点，数据全部合成')+metric('较高环境风险',sites.filter(s=>risk(s)>=70).length,'个','演示阈值：风险指数 ≥ 70')+metric('缺少现场调查',sites.filter(s=>s.evidence!=='A').length,'个','报告与未知地点优先补充证据')+metric('当前预警目标',`+${state.horizon}`,'天','预测目标日，不是环境响应时滞');}
const reefMap=createReefMap({geo,onSelect:selectSite});
$('map-focus').onclick=()=>reefMap.focus();$('map-reset').onclick=()=>reefMap.reset();
const compoundUI=setupCompoundUI();
function drawMap(){reefMap.update(visible(),state.site,state.layer,risk,color);const legends=state.layer==='risk'?[['#72b9a5','<40'],['#e5c27d','40–69'],['#ec9178','≥70']]:state.layer==='evidence'?[['#67c0aa','模拟调查'],['#e0c185','模拟报告'],['#90a1aa','未知']]:[['#b7a2d8','模拟随访'],['#82939c','未评估']];$('map-legend').innerHTML=legends.map(([c,t])=>`<span class="legend-item"><i class="dot" style="background:${c}"></i>${t}</span>`).join('');}
function drawSite(){const s=state.site,r=risk(s);$('site-id').textContent=s.id;$('site-name').textContent=s.name;$('site-meta').textContent=`${s.en} · ${s.lat.toFixed(1)}°, ${s.lon.toFixed(1)}°`;$('site-risk').innerHTML=`<div class="risk-line"><div><div class="risk-title">第 ${state.horizon} 天情景风险指数</div><div class="risk-value" style="color:${color(r)}">${r}<small> / 100</small></div></div><span class="pill ${r>=70?'warn':''}">${r>=70?'优先核查':r>=40?'持续关注':'相对较低'}</span></div>`;
const rows=[['环境暴露',`DHW ${s.dhw} °C·周 · 合成`],['白化证据',evidence(s)],['调查信息',s.survey?`${s.survey}${s.sample?` · ${s.sample} 个样本`:''}`:'无调查记录'],['生态后果',s.outcome?`${s.outcome}：${s.outcome==='恢复随访'?'同一合成样带 18% → 0% 白化；未发现死亡':'同一合成样带 85 个样本中记录 8 个死亡'}；非白化率推算`:'恢复 / 死亡均未评估']];
$('site-evidence').innerHTML=rows.map(([a,b])=>`<div class="evidence-row"><span>${a}</span><b>${b}</b></div>`).join('');$('next-action').textContent=`下一步 · ${next(s)}。`;drawScenario();drawChart();}
function drawScenario(){const s=state.site,base=risk(s),changed=scenarioRisk(s,state.horizon,state.delta);$('scenario-result').innerHTML=`<span>基准 <strong>${base}</strong></span><span>→</span><span>假设情景 <strong style="color:${color(changed)}">${changed}</strong></span><span class="pill">${changed-base>=0?'+':''}${changed-base} 点</span><span style="margin-left:auto;color:#809894">证据不变</span>`;}
function drawChart(){const s=state.site,random=rng(Number(s.id.slice(-2))*7),vals=Array.from({length:30},(_,i)=>Math.max(0,s.dhw*(.38+.62*i/29)+.5*Math.sin(i/4)+(random()-.5)*.6));const max=14,x=i=>38+i*13.5,y=v=>145-v/max*120;let svg='<svg viewBox="0 0 455 180" role="img" aria-label="模拟的过去30天DHW热应激序列">';for(let v=0;v<=12;v+=4)svg+=`<line x1="38" x2="435" y1="${y(v)}" y2="${y(v)}" stroke="#e5ecec" stroke-dasharray="3 4"/><text x="20" y="${y(v)+3}" font-size="9" fill="#8aa0a7">${v}</text>`;const points=vals.map((v,i)=>`${x(i)},${y(v)}`);svg+=`<path d="M38,145 L${points.join(' L')} L${x(29)},145Z" fill="#e98066" opacity=".08"/><polyline points="${points.join(' ')}" stroke="#e8957c" stroke-width="2.4" fill="none"/>`;if(s.survey){const offset=Number(s.survey.slice(-2))-15,idx=29+offset;svg+=`<line x1="${x(idx)}" x2="${x(idx)}" y1="${y(vals[idx])-10}" y2="145" stroke="#76b4a1" stroke-dasharray="3 3"/><circle cx="${x(idx)}" cy="${y(vals[idx])}" r="4" fill="#62ad98"/><text x="${x(idx)}" y="${y(vals[idx])-17}" text-anchor="middle" font-size="9" fill="#6d9e90">模拟调查</text>`;}svg+='<text x="38" y="167" font-size="9" fill="#8aa0a7">05 / 17</text><text x="210" y="167" font-size="9" fill="#8aa0a7">06 / 01</text><text x="400" y="167" font-size="9" fill="#8aa0a7">06 / 15</text></svg>';$('chart').innerHTML=svg;}
function drawTable(){const sites=[...visible()].sort((a,b)=>risk(b)-risk(a));$('priority-table').innerHTML=sites.map((s,i)=>`<tr><td><button data-site="${s.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span>${s.name}</button></td><td>${s.basin}</td><td><span class="risk-bar"><span style="background:${color(risk(s))};width:${risk(s)}%"></span></span>${risk(s)}</td><td class="${s.evidence==='U'?'status-u':'status-e'}">${evidence(s)}</td><td>${outcome(s)}</td><td>${s.evidence==='U'?'补充现场调查':s.evidence==='B'?'核验事件报告':'重复调查与随访'}</td></tr>`).join('');$('priority-table').querySelectorAll('[data-site]').forEach(b=>b.onclick=()=>{selectSite(b.dataset.site);$('site-name').scrollIntoView({behavior:'smooth',block:'center'});});}
function resetSliders(){for(const key of ['heat','light','mixing']){state.delta[key]=0;$(key).value=0;$(`${key}-out`).textContent=key==='heat'?'+0 °C·周':'+0';}}
function selectSite(id){state.site=SITES.find(s=>s.id===id);resetSliders();drawMap();drawSite();}
function render(){drawSummary();drawMap();drawSite();drawTable();comparisonVisuals(visible(),state.horizon);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.page,.nav').forEach(p=>p.classList.remove('active'));$(b.dataset.tab).classList.add('active');b.classList.add('active');history.replaceState(null,'',`#${b.dataset.tab}`);window.scrollTo({top:0,behavior:'smooth'});if(b.dataset.tab==='overview')reefMap.resize();});
document.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{state.horizon=Number(b.dataset.h);document.querySelectorAll('[data-h]').forEach(el=>el.classList.toggle('selected',el===b));render();});
document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>{state.layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(el=>el.classList.toggle('selected',el===b));drawMap();});
$('basin').onchange=e=>{state.basin=e.target.value;if(!visible().includes(state.site))state.site=visible()[0];resetSliders();render();};
for(const key of ['heat','light','mixing'])$(key).oninput=e=>{const v=Number(e.target.value);state.delta[key]=v;$(`${key}-out`).textContent=`${v>=0?'+':''}${v}${key==='heat'?' °C·周':''}`;drawScenario();};
$('reset').onclick=()=>{resetSliders();drawScenario();};
function siteCard(){return {dataKind:'synthetic',version:VERSION,geography:{land:'Natural Earth',reef_context:'Allen Coral Atlas official link; online layer availability varies',no_biological_ground_truth:true},displaySnapshot:'2026-06-15',horizon:state.horizon,site:state.site,environmentRiskIndex:risk(state.site),scenario:{delta:state.delta,index:scenarioRisk(state.site,state.horizon,state.delta)},priorityAction:next(state.site),boundary:'Environment index is not a calibrated probability. Bleaching is not mortality. Missing observation is unknown.'};}
$('download-site').onclick=()=>{download(`${state.site.id}-synthetic-evidence.json`,JSON.stringify(siteCard(),null,2));notify('本站证据卡已导出，包含合成数据标识。');};
$('download-csv').onclick=()=>{const rows=[['data_kind','site_id','name','basin','horizon_days','risk_index','evidence_level','bleaching_pct','outcome'],...[...visible()].sort((a,b)=>risk(b)-risk(a)).map(s=>['synthetic',s.id,s.name,s.basin,state.horizon,risk(s),s.evidence,s.bleaching??'',outcome(s)])];download('synthetic-monitoring-priority.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');};
$('export-report').onclick=()=>download('CoralBleach-research-brief.md',`# CoralBleach-Agent 研究简报\n\n全部数值为合成演示，非真实监测结果。\n\n## 当前站点\n${state.site.name}，未来第 ${state.horizon} 天情景风险指数 ${risk(state.site)}/100。\n${evidence(state.site)}；生态后果：${outcome(state.site)}。\n下一步：${next(state.site)}。\n\n## 科学边界\n热应激不等于白化观测，白化不等于死亡。没有调查不代表没有白化。\n\n## 本轮实验\n${state.run?JSON.stringify({winner:state.run.adaptive?.winner||state.run.final?.candidate,final:state.run.final},null,2):'尚未运行。'}\n`,'text/markdown;charset=utf-8');
function drawRun(result){state.run=result;budgetVisual(result);$('run-description').textContent=result.track==='compound'?'本轮记录：氮形态与共污染 / '+accessLabels[result.access]+' / '+worldLabels[result.world]+'。下方为运行时配置的结果，修改选项后需重新运行。':'本轮记录：时滞与空间信号路线，v1.0 生成器。下方为运行时配置的结果。';$('lab-result').classList.remove('hidden');$('export-run').disabled=false;const f=result.final.adaptive;$('lab-metrics').innerHTML=metric('封存测试 AP',fmt(f.ap),'','仅表示本次合成测试排序')+metric('Brier skill',fmt(f.bss),'','参考概率来自训练集')+metric('Top-20% 容量召回',f.recall20==null?'—':`${Math.round(f.recall20*100)}%`,'',`选中 ${f.k} 条，命中 ${f.captured}，误报 ${f.falseAlarms}`)+metric('质量门控',f.status==='DEFER'?'暂缓':'已评估','',`测试 ${f.n} 条，阳性 ${f.positives} 条`);
$('trace').innerHTML=result.adaptive.log.map(l=>`<div class="trace-row"><span class="step-no">${l.step}</span><span>${route[l.candidate.route]} · 滞后 ${l.candidate.lag} 天 · ${model[l.candidate.model]}<small>效用 ${fmt(l.utility)} · 剩余 ${l.remaining} 步</small></span><span>AP ${fmt(l.metrics.ap)}</span></div>`).join('');
const labels={adaptive:'自适应选择',random:'随机搜索',local:result.track==='compound'?'热暴露基线':'局地基线',climatology:'训练发生率'};$('comparison').innerHTML=Object.entries(result.final).map(([key,m])=>`<div class="metric-bar"><span>${labels[key]}</span><div><span style="width:${(m.ap??0)*100}%;background:${key==='adaptive'?'#db947c':'#83ac9d'}"></span></div><b>${fmt(m.ap)}</b></div>`).join('');
const names={none:result.track==='compound'?'原始输入':'正向连接',reverse:'反向连接',ablate:'移除化学信息','time-shift':'错时输入'};$('control-caption').textContent=result.track==='compound'?'对冻结赢家移除化学信息，或将候选输入再提前31天。同一分区重新拟合；不构成因果或统计显著性检验。':'方向对照固定为方向性 / 滞后7天 / 交互项，与赢家无关。时间对照将输入再提前31天。';$('controls').innerHTML=`<div class="control-card"><b>${result.track==='compound'?'冻结赢家':'固定方向候选'}的对照 / 测试 AP</b>${result.controls.map(c=>`<p>${names[c.control]} <span style="float:right">${fmt(c.metrics.ap)}</span></p>`).join('')}</div>`;
const win=result.adaptive.winner,delta=(f.ap??0)-(result.final.local.ap??0);$('finding').innerHTML=`<p>在种子 <b>${result.seed}</b>、目标日 <b>+${result.horizon} 天</b>、预算 <b>${result.budget} 步</b>下，验证集选择了 <b>${route[win.route]} / 滞后 ${win.lag} 天 / ${model[win.model]}</b>。其封存测试 AP 相对局地基线变化为 <b>${delta>=0?'+':''}${fmt(delta)}</b>。</p><p>${f.status==='DEFER'?'测试集阳性或阴性少于10条，本轮暂缓性能判断。':delta>0?'本次合成运行出现排序增益。需要多种子、不同生成条件与真实观测验证其稳定性。':'本次合成运行没有获得相对局地基线的排序增益，保留该负结果。'}</p><p>这张发现卡记录软件实验结果。真实海流传导、白化预测精度、恢复和死亡结论均未由本轮实验建立。</p>`;
$('run-status').textContent=`计算完成 · ${result.adaptive.log.length} 次自适应实验 + ${result.random.log.length} 次同预算随机实验 · 两个候选锁定后才开启封存测试集。`;}
let currentLLM=null,activeWorker=null;
const modelSetup=setupModels();
setupWetLab({modelSetup,notify,download});
document.querySelectorAll('[data-lab-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-lab-view]').forEach(n=>n.classList.toggle('active',n===b));$('wetlab-root').classList.toggle('hidden',b.dataset.labView!=='wet');$('computational-lab').classList.toggle('hidden',b.dataset.labView!=='computational');});
$('run').onclick=async()=>{const seed=Number($('seed').value);if(!Number.isInteger(seed)||seed<1||seed>999999){notify('请输入 1–999999 的整数种子。');return;}const config={seed,horizon:Number($('lab-horizon').value),budget:Number($('budget').value),mode:$('planner-mode').value,question:$('research-question').value,...compoundUI.config()};
let connection=null;
if(config.mode==='llm'){try{connection=await modelSetup.prepare(config.budget);config.modelId=connection.modelId;config.model=connection.model;config.runId=connection.runId;config.transport=connection.transport;}catch(error){$('provider-status').textContent=error.message;notify(error.message);return;}}
state.run=null;currentLLM=null;$('run').disabled=true;$('export-run').disabled=true;$('lab-result').classList.add('hidden');$('llm-result').classList.add('hidden');$('run-status').textContent=config.mode==='llm'?'大模型正在诊断场景并选择科学模型…':'正在生成合成环境并拟合候选模型…';const worker=new Worker('worker.js',{type:'module'});activeWorker=worker;modelSetup.lock(true);$('stop-run').classList.remove('hidden');worker.onmessage=e=>{if(e.data.progress){$('run-status').textContent=`大模型规划第 ${e.data.progress.step} 轮 · 实验 ${e.data.progress.used}/${e.data.progress.budget}`;return;}if(e.data.error){$('run-status').textContent='计算未完成：'+e.data.error;}else if(e.data.llm){currentLLM=e.data;state.run=e.data.llm;drawLLM(e.data.llm);$('llm-result').classList.remove('hidden');$('export-run').disabled=false;$('interpret').disabled=!e.data.llm.final;$('llm-audit').textContent=e.data.llm.audit.map(a=>`第 ${a.step} 轮 · ${a.tool||a.status} · ${a.status}\n${a.rationale||a.error||''}\n${JSON.stringify(a.result||{},null,2)}`).join('\n\n');$('run-status').textContent=`大模型运行状态：${e.data.llm.status} · 实验 ${e.data.llm.experiments_executed}/${config.budget} · ${e.data.llm.planning_calls} 次规划调用`;$('llm-interpretation').textContent=e.data.llm.final?`封存测试 AP ${fmt(e.data.llm.final.metrics.ap)}；局地基线 ${fmt(e.data.llm.final.local.ap)}。模型已经冻结，测试结果不再用于本轮实验选择。`:'未满足冻结条件，未读取封存测试集。';}else drawRun(e.data);$('run').disabled=false;worker.terminate();activeWorker=null;modelSetup.lock(false);$('stop-run').classList.add('hidden');};worker.onerror=()=>{$('run-status').textContent='实验加载失败，请通过HTTP服务或部署网址打开本站。';$('run').disabled=false;worker.terminate();activeWorker=null;modelSetup.lock(false);$('stop-run').classList.add('hidden');};worker.postMessage({config,connection});connection=null;};
$('export-run').onclick=()=>{if(state.run)download('coralbleach-experiment.json',JSON.stringify(state.run,null,2));};
$('stop-run').onclick=()=>{if(activeWorker){activeWorker.terminate();activeWorker=null;modelSetup.lock(false);$('run').disabled=false;$('stop-run').classList.add('hidden');$('run-status').textContent='本轮已停止，未开启封存测试；已发送的模型请求可能仍计入平台用量。';}};
$('interpret').onclick=async()=>{if(!currentLLM)return;$('interpret').disabled=true;try{const r=await modelSetup.interpret(currentLLM);$('llm-interpretation').textContent=r.text;}catch(error){$('llm-interpretation').textContent=error.message;}};
$('snapshot-date').textContent='2026-06-15 / 固定演示时点';render();const initial=location.hash.slice(1);if(['lab','science'].includes(initial))document.querySelector(`[data-tab="${initial}"]`).click();

function drawLLM(result){
 const labels={inspect_data:'诊断数据场景',select_models:'选择科学模型',evaluate_hypothesis:'运行候选实验',negative_control:'检验反例',finish:'冻结研究方案'};
 const summary=document.getElementById('llm-summary');summary.replaceChildren();
 for(const [value,label] of [[result.experiments_executed+'/'+result.config.budget,'实验预算'],[result.planning_calls,'规划调用'],[result.known_total_tokens+(result.token_usage_complete?'':' + 未知'),'已报告 Token'],[result.final?'已冻结':'未冻结','测试集门控']]){const card=document.createElement('div');card.className='metric';const b=document.createElement('b');b.textContent=value;const p=document.createElement('p');p.textContent=label;card.append(b,p);summary.append(card);}
 const timeline=document.getElementById('llm-timeline');timeline.replaceChildren();
 for(const entry of result.audit){const row=document.createElement('div');row.className='llm-step';const number=document.createElement('span');number.textContent=String(entry.step).padStart(2,'0');const body=document.createElement('div');const title=document.createElement('b');title.textContent=labels[entry.tool]||'规划未完成';const reason=document.createElement('p');reason.textContent=entry.rationale||entry.error||entry.result?.error||entry.status;body.append(title,reason);if(entry.result?.metrics){const metric=document.createElement('small');metric.textContent=`验证 AP ${fmt(entry.result.metrics.ap)} · Brier ${fmt(entry.result.metrics.brier)} · 剩余实验 ${entry.result.budget_remaining}`;body.append(metric);}row.append(number,body);timeline.append(row);}
}
